cd /tmp/ross-main
python3 - <<'PY'
import subprocess,re,glob
# all friend msg commits
branches=['rachel','monica','phoebe','joey','chandler','ross']
commits={}
for b in branches:
    out=subprocess.check_output(['git','log',f'origin/friend/{b}','--format=%H'], text=True).split()
    for sha in out:
        msg=subprocess.check_output(['git','show','-s','--format=%B',sha], text=True)
        if 'Friend-Message: 1' in msg:
            commits[sha]=b
sources=set()
for f in glob.glob('S*/*.md'):
    for line in open(f):
        m=re.match(r'Source: friend/\w+ @ ([0-9a-f]{40})', line.strip())
        if m: sources.add(m.group(1))
missing=[s for s in commits if s not in sources]
print('missing count', len(missing))
for s in missing:
    msg=subprocess.check_output(['git','show','-s','--format=%B',s], text=True)
    ep=re.search(r'Episode:\s*(.+)',msg).group(1).strip()
    sp=re.search(r'Speaker:\s*(.+)',msg).group(1).strip()
    ci=subprocess.check_output(['git','show','-s','--format=%ci',s], text=True).strip()
    print(ci, commits[s], ep, sp, s)
PY
